// Normalizar y limpiar noticias de los feeds con enlaces directos verificados
const items = $input.all();
const cleaned = [];
const seenTitles = new Set();
let idCounter = 0;

for (const item of items) {
  const json = item.json;
  const title = (json.title || '').trim();
  if (!title || seenTitles.has(title.toLowerCase())) continue;
  seenTitles.add(title.toLowerCase());

  // Limpieza de extracto HTML
  let rawSnippet = json.contentSnippet || json.content || json.description || '';
  rawSnippet = rawSnippet.replace(/<[^>]*>?/gm, '').replace(/\s+/g, ' ').trim().slice(0, 400);

  // Extracción robusta de URL verdadera (evitar [object Object] o undefined)
  let directLink = '';
  if (typeof json.link === 'string' && json.link.startsWith('http')) directLink = json.link;
  else if (typeof json.origLink === 'string' && json.origLink.startsWith('http')) directLink = json.origLink;
  else if (typeof json['feedburner:origLink'] === 'string') directLink = json['feedburner:origLink'];
  else if (typeof json.guid === 'string' && json.guid.startsWith('http')) directLink = json.guid;

  if (!directLink) continue;

  // Extracción de imagen de medios si existe
  let imageUrl = '';
  if (json.enclosure && json.enclosure.url) imageUrl = json.enclosure.url;
  else if (json['media:content'] && json['media:content'].$ && json['media:content'].$.url) imageUrl = json['media:content'].$.url;

  cleaned.push({
    raw_id: idCounter++,
    title: title,
    link: directLink,
    pubDate: json.pubDate || new Date().toISOString(),
    source: json.creator || json['dc:creator'] || 'Tech Source',
    snippet: rawSnippet,
    image: imageUrl
  });
}

// Tomar las 10 noticias más relevantes
return [{ json: { raw_news: cleaned.slice(0, 10) } }];

// Extraer el JSON generado por Gemini y recuperar los enlaces inmutables originales de raw_news
// Garantiza 0% enlaces rotos 404 al no depender de URLs generadas por LLM
const rawNews = $('Filtrar & Limpiar Feeds').first().json.raw_news || [];
const geminiOutput = $('Gemini AI Synthesizer').first().json.text || '';
const currentFileSha = $json.sha;

// Limpiar bloques Markdown de la respuesta
let cleanJson = geminiOutput.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { noticias: [] };
}

const defaultImages = {
  'ia': 'https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&w=1200&q=80',
  'gaming': 'https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=80',
  'tecnologia': 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80',
  'software': 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=1200&q=80'
};

const newsList = Array.isArray(parsed.noticias) ? parsed.noticias : [];
const mergedNoticias = newsList.map((item, idx) => {
  const raw = (item.raw_id !== undefined && rawNews[item.raw_id]) ? rawNews[item.raw_id] : (rawNews[idx] || {});
  const slug = item.categoria_slug || 'tecnologia';

  return {
    id: `news-${idx + 1}`,
    titulo: item.titulo || raw.title || 'Noticia Tecnológica',
    categoria: item.categoria || 'Tecnología',
    categoria_slug: slug,
    destacada: item.destacada ?? (idx === 0),
    resumen: item.resumen || raw.snippet || '',
    contenido_extendido: item.contenido_extendido || `Reporte original publicado por ${raw.source || 'la fuente'}.`,
    imagen: raw.image || defaultImages[slug] || defaultImages['tecnologia'],
    fecha: raw.pubDate ? new Date(raw.pubDate).toLocaleDateString('es-ES', { day: '2-digit', month: 'short', year: 'numeric' }) : new Date().toLocaleDateString('es-ES'),
    tiempo_lectura: item.tiempo_lectura || '3 min',
    fuente_nombre: raw.source || 'Medio Oficial',
    // ENLACE DIRECTO VERDADERO INMUTABLE DESDE EL FEED ORIGINAL
    fuente_url: raw.link || 'https://news.google.com',
    tags: Array.isArray(item.tags) && item.tags.length > 0 ? item.tags : ['Tech', 'Innovación']
  };
});

const finalData = {
  ultima_actualizacion: new Date().toISOString(),
  agente: "GiraTek Autonomous News Engine v2.5 (Gemini AI + Direct Feed Resolver)",
  total: mergedNoticias.length,
  noticias: mergedNoticias
};

let jsonString = JSON.stringify(finalData, null, 2);
let base64Content = Buffer.from(jsonString, 'utf-8').toString('base64');

return [{
  json: {
    message: `Auto-update: Noticias tech ${new Date().toISOString().slice(0, 10)} [GiraTek agent]`,
    content: base64Content,
    sha: currentFileSha
  }
}];
